// Trend -> arrow image. PNGs are generated by tools/gen_assets.py.

const TREND_ICONS = Object.freeze({
  DOUBLE_UP: '/common/trend/up2.png',
  SINGLE_UP: '/common/trend/up.png',
  FORTY_FIVE_UP: '/common/trend/up45.png',
  FLAT: '/common/trend/flat.png',
  FORTY_FIVE_DOWN: '/common/trend/down45.png',
  SINGLE_DOWN: '/common/trend/down.png',
  DOUBLE_DOWN: '/common/trend/down2.png'
})

/** Image path for a trend, or '' when there is nothing to draw (NONE/unknown). */
export function trendIcon(trend) {
  return TREND_ICONS[trend] || ''
}
